Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
zscoder has a deck of $$$n+m$$$ custom-made cards, which consists of $$$n$$$ cards labelled from $$$1$$$ to $$$n$$$ and $$$m$$$ jokers. Since zscoder is lonely, he wants to play a game with himself using those cards. Initially, the deck is shuffled uniformly randomly and placed on the table. zscoder has a set $$$S$$$ which is initially empty. Every second, zscoder draws the top card from the deck.   If the card has a number $$$x$$$ written on it, zscoder removes the card and adds $$$x$$$ to the set $$$S$$$.  If the card drawn is a joker, zscoder places all the cards back into the deck and reshuffles (uniformly randomly) the $$$n+m$$$ cards to form a new deck (hence the new deck now contains all cards from $$$1$$$ to $$$n$$$ and the $$$m$$$ jokers). Then, if $$$S$$$ currently contains all the elements from $$$1$$$ to $$$n$$$, the game ends. Shuffling the deck doesn't take time at all. What is the expected number of seconds before the game ends? We can show that the answer can be written in the form $$$\frac{P}{Q}$$$ where $$$P, Q$$$ are relatively prime integers and $$$Q \neq 0 \bmod 998244353$$$. Output the value of $$$(P \cdot Q^{-1})$$$ modulo $$$998244353$$$.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String[] tokens = br.readLine().trim().split(" +");
            int n = Integer.parseInt(tokens[0]);
            int m = Integer.parseInt(tokens[1]);

            Mod998 mod = new Mod998();

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; p != 0; i++) {
                long numerator = n - i;
                long denominator = n + m - i;
                p = mod.mult(p, numerator, mod.inv(denominator));
                phaseSize = mod.add(phaseSize, p);
            }

            long total = 0;
            for (int k = 1; k <= n; k++) {
                long sign = ((k + 1) % 2 == 0) ? 1 : mod.modulus() - 1;
                long prNoSpecial = mod.div(
                    mod.ncr(m + k - 1, k),
                    mod.ncr(m + k, k)
                );
                long oneMinusPr = mod.subtract(1, prNoSpecial);
                long numPhases = mod.inv(oneMinusPr);
                long e = mod.mult(numPhases, phaseSize);
                long comb = mod.ncr(n, k);
                long term = mod.mult(comb, e);
                total = mod.add(total, mod.mult(sign, term));
            }

            pw.println(total);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static class Mod998 extends Modulus<Mod998> {
        @Override
        public long modulus() {
            return 998_244_353L;
        }
    }

    static abstract class Modulus<M extends Modulus<M>> {
        private final List<Long> factCache = new ArrayList<>();
        private final List<Long> invFactCache = new ArrayList<>();

        public abstract long modulus();

        public Modulus() {
            factCache.add(1L);
            invFactCache.add(1L);
        }

        public long fact(int n) {
            while (factCache.size() <= n) {
                int size = factCache.size();
                factCache.add(mult(factCache.get(size - 1), (long) size));
            }
            return factCache.get(n);
        }

        public long fInv(int n) {
            int last = invFactCache.size() - 1;
            if (last < n) {
                int needed = n - last;
                long[] buffer = new long[needed];
                buffer[0] = inv(fact(n));
                for (int i = 1; i < needed; i++) {
                    buffer[i] = mult(buffer[i - 1], n - i + 1);
                }
                for (int i = needed - 1; i >= 0; i--) {
                    invFactCache.add(buffer[i]);
                }
            }
            return invFactCache.get(n);
        }

        public long paritySign(long k) {
            return (k % 2 == 0) ? 1 : modulus() - 1;
        }

        public long ncr(int n, int r) {
            if (r < 0 || n < r) return 0;
            return mult(fact(n), mult(fInv(r), fInv(n - r)));
        }

        public long normalize(long x) {
            x %= modulus();
            return x < 0 ? x + modulus() : x;
        }

        public long add(long a, long b) {
            long sum = a + b;
            return sum < modulus() ? sum : sum - modulus();
        }

        public long subtract(long a, long b) {
            long diff = a - b;
            return diff < 0 ? diff + modulus() : diff;
        }

        public long mult(long... values) {
            long res = 1;
            for (long val : values) res = mult(res, val);
            return res;
        }

        public long mult(long a, long b) {
            return (a * b) % modulus();
        }

        public long div(long a, long b) {
            return mult(a, inv(b));
        }

        public long inv(long val) {
            long g = modulus(), x = 0, y = 1;
            for (long r = val; r != 0; ) {
                long q = g / r;
                g %= r;
                long tmp = g;
                g = r;
                r = tmp;
                x -= q * y;
                tmp = x;
                x = y;
                y = tmp;
            }
            return normalize(x);
        }
    }
}
